  const SPRITE_ID = 'badminton-icon-sprite';
  const SVG_NAMESPACE = 'http://www.w3.org/2000/svg';

  // ── 02｜安裝同頁圖示集：零尺寸且不接收焦點，不影響版面與讀屏順序。 ──
  function mountSprite() {
    if (!document.body || document.getElementById(SPRITE_ID)) return;

    const sprite = document.createElementNS(SVG_NAMESPACE, 'svg');
    sprite.id = SPRITE_ID;
    sprite.setAttribute('aria-hidden', 'true');
    sprite.setAttribute('focusable', 'false');
    sprite.setAttribute('width', '0');
    sprite.setAttribute('height', '0');
    sprite.style.cssText = 'position:absolute;width:0;height:0;overflow:hidden;pointer-events:none';
    sprite.innerHTML = Object.entries(ICONS).map(([name, paths]) => (
      `<symbol id="bi-${name}" viewBox="0 0 16 16">${paths}</symbol>`
    )).join('');
    document.body.prepend(sprite);
  }

  // ── 03｜產生圖示：名稱只取白名單，額外 class 僅接受安全的類別字元。 ──
  function svg(name, className = '') {
    if (typeof name !== 'string' || !Object.hasOwn(ICONS, name)) return '';

    const extraClasses = typeof className === 'string'
      ? className.split(/\s+/).filter((part) => /^[a-zA-Z0-9_-]+$/.test(part))
      : [];
    const classes = ['bi', `bi-${name}`, ...extraClasses].join(' ');

    return `<svg class="${classes}" viewBox="0 0 16 16" width="1em" height="1em" fill="currentColor" aria-hidden="true" focusable="false"><use href="#bi-${name}"></use></svg>`;
  }

  // ── 04｜靜態圖示：在空白 span 上填 data-icon="圖示名稱" 即可使用。 ──
  // 保留容器本身的 class；動態產生的按鈕可直接呼叫 svg()，或再呼叫 hydrate()。
  function hydrate(root = document) {
    mountSprite();
    root.querySelectorAll('[data-icon]').forEach((holder) => {
      const markup = svg(holder.getAttribute('data-icon'));
      if (!markup) return;
      holder.innerHTML = markup;
      if (holder.tagName.toLowerCase() === 'span') {
        holder.setAttribute('aria-hidden', 'true');
      }
    });
  }

  // ── 05｜對外介面與初始化：放在 body 底部時立即填入靜態圖示。 ──
  globalThis.BadmintonIcons = Object.freeze({ svg, hydrate, version: '1.13.1' });
  if (document.body) hydrate();
  else document.addEventListener('DOMContentLoaded', () => hydrate(), { once: true });
